CREATE FUNCTION fyf_delivery_quote_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'Delivery quote history is append-only' USING ERRCODE='23514';
END;
$$;
--> statement-breakpoint
CREATE TRIGGER delivery_quote_revisions_immutable BEFORE UPDATE OR DELETE ON delivery_quote_revisions FOR EACH ROW EXECUTE FUNCTION fyf_delivery_quote_append_only();
--> statement-breakpoint
