CREATE FUNCTION fyf_delivery_quote_preserve_request() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Delivery requests are retained' USING ERRCODE='23514'; END IF;
  IF (to_jsonb(OLD)-'status'-'version'-'assigned_to'-'updated_at') IS DISTINCT FROM (to_jsonb(NEW)-'status'-'version'-'assigned_to'-'updated_at') OR NEW.version<>OLD.version+1 THEN
    RAISE EXCEPTION 'Request cargo, owner and destination are immutable; version must advance' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER delivery_quote_request_guard BEFORE UPDATE OR DELETE ON delivery_quote_requests FOR EACH ROW EXECUTE FUNCTION fyf_delivery_quote_preserve_request();
--> statement-breakpoint
CREATE FUNCTION fyf_delivery_quote_approve_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE source delivery_quote_revisions%ROWTYPE; request delivery_quote_requests%ROWTYPE; policy delivery_policy_revisions%ROWTYPE;
BEGIN
  IF NEW.kind<>'APPROVED' THEN RETURN NEW; END IF;
  SELECT * INTO source FROM delivery_quote_revisions WHERE id=NEW.source_revision_id AND request_id=NEW.request_id;
  SELECT * INTO request FROM delivery_quote_requests WHERE id=NEW.request_id;
  SELECT * INTO policy FROM delivery_policy_revisions WHERE id=NEW.policy_revision_id;
  IF source.id IS NULL OR source.kind<>'PROPOSAL' OR request.status<>'PROPOSED' OR source.version<>(SELECT max(version) FROM delivery_quote_revisions WHERE request_id=NEW.request_id)
    OR (NEW.amount,NEW.reason,NEW.vehicle,NEW.distance_km,NEW.trips,NEW.route_confirmed,NEW.coordinated,NEW.notes,NEW.customer_note)
       IS DISTINCT FROM (source.amount,source.reason,source.vehicle,source.distance_km,source.trips,source.route_confirmed,source.coordinated,source.notes,source.customer_note)
    OR NOT EXISTS(SELECT 1 FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=NEW.created_by AND u.status='ACTIVE' AND r.name IN ('ADMIN','MANAGER'))
    OR policy.pricing_mode IS DISTINCT FROM 'MANUAL_QUOTE' OR NOT policy.delivery_enabled THEN
    RAISE EXCEPTION 'Approval requires an authorized actor and its unchanged proposal' USING ERRCODE='23514';
  END IF;
  IF NEW.reason='FREE_CONDITIONAL' AND (NOT request.non_urgent OR NOT NEW.coordinated OR NOT policy.conditional_free_enabled OR NEW.products_net IS NULL OR NEW.threshold_snapshot IS DISTINCT FROM policy.conditional_free_from OR NEW.products_net<policy.conditional_free_from) THEN
    RAISE EXCEPTION 'Conditional free freight was not approved under valid conditions' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER delivery_quote_approval_guard BEFORE INSERT ON delivery_quote_revisions FOR EACH ROW EXECUTE FUNCTION fyf_delivery_quote_approve_guard();
--> statement-breakpoint
CREATE FUNCTION fyf_delivery_quote_token_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP='DELETE' OR (to_jsonb(OLD)-'revoked_at') IS DISTINCT FROM (to_jsonb(NEW)-'revoked_at') OR OLD.revoked_at IS NOT NULL THEN
    RAISE EXCEPTION 'Access tokens can only be revoked' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER delivery_quote_token_guard BEFORE UPDATE OR DELETE ON guest_delivery_quote_tokens FOR EACH ROW EXECUTE FUNCTION fyf_delivery_quote_token_guard();
--> statement-breakpoint
CREATE FUNCTION fyf_online_order_manual_quote_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP='UPDATE' AND (NEW.delivery_quote_request_id,NEW.delivery_quote_acceptance_id) IS DISTINCT FROM (OLD.delivery_quote_request_id,OLD.delivery_quote_acceptance_id) THEN
    RAISE EXCEPTION 'Historical order quotation references cannot change' USING ERRCODE='23514';
  END IF;
  IF NEW.delivery_quote_request_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM delivery_quote_events e WHERE e.id=NEW.delivery_quote_acceptance_id AND e.request_id=NEW.delivery_quote_request_id AND e.type='ACCEPTED') THEN
    -- ACCEPTED is deliberately not an allowed event in 3A. Phase 3B needs explicit authorization.
    RAISE EXCEPTION 'Manual delivery checkout is not enabled without accepted commercial terms' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER online_order_manual_quote_guard BEFORE INSERT OR UPDATE ON online_orders FOR EACH ROW EXECUTE FUNCTION fyf_online_order_manual_quote_guard();
